diff --git a/tests/DomainTests/Program.cs b/tests/DomainTests/Program.cs
index 567d981..70f002c 100644
--- a/tests/DomainTests/Program.cs
+++ b/tests/DomainTests/Program.cs
@@ -8,8 +8,12 @@ void Check(string sc, string name, Func<bool> f)
     Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {sc} {name}");
     if (!ok) failures++;
 }
-Check("v1-1", "尚未出貨可取消", () => Cancellation.Cancel(new Order(false, false, false)).Order.Cancelled);
-Check("v1-2", "已出貨不可取消", () => { var o = new Order(true, false, false); return Cancellation.Cancel(o).Order == o; });
-Check("v1-3", "已付款取消不要求退款", () => { var r = Cancellation.Cancel(new Order(false, true, false)); return r.Order.Cancelled && !r.RefundRequested; });
+Check("SC-01", "未出貨可取消", () => { var r = Cancellation.Cancel(new Order(false, false, false)); return r.Order.Cancelled && !r.RefundRequested; });
+Check("SC-02", "已出貨不可取消", () => { var o = new Order(true, false, false); return Cancellation.Cancel(o).Order == o; });
+Check("SC-03", "已付款取消要求退款", () => { var r = Cancellation.Cancel(new Order(false, true, false)); return r.Order.Cancelled && r.RefundRequested; });
+Check("SC-04", "未付款取消不要求退款", () => { var r = Cancellation.Cancel(new Order(false, false, false)); return !r.RefundRequested; });
+Check("SC-05", "已出貨已付款回傳原訂單不退款", () => { var o = new Order(true, true, false); var r = Cancellation.Cancel(o); return r.Order == o && !r.RefundRequested; });
+Check("SC-06", "已取消未付款再次取消維持原狀不退款", () => { var o = new Order(false, false, true); var r = Cancellation.Cancel(o); return r.Order == o && !r.RefundRequested; });
+Check("SC-07", "已取消已付款再次取消不重複退款", () => { var o = new Order(false, true, true); var r = Cancellation.Cancel(o); return r.Order == o && !r.RefundRequested; });
 Console.WriteLine(failures == 0 ? "PASS: 全部條件通過" : $"FAIL: {failures} 項條件未通過");
 return failures;

1	namespace OrderCancel.Domain;
2	
3	public record Order(bool Shipped, bool Paid, bool Cancelled);
4	public record CancellationResult(Order Order, bool RefundRequested);
5	
6	public static class Cancellation
7	{
8	    public static CancellationResult Cancel(Order order)
9	    {
10	        // 已出貨的訂單不可取消：維持原訂單，Cancelled 不變，不丟例外（decisions.md 第2列）
11	        if (order.Shipped)
12	        {
13	            return new CancellationResult(order, RefundRequested: false);
14	        }
15	
16	        // 已取消的訂單再次取消：維持原狀、不重複退款（rules-v2.md BR-04）
17	        if (order.Cancelled)
18	        {
19	            return new CancellationResult(order, RefundRequested: false);
20	        }
21	
22	        // 尚未出貨、尚未取消的訂單可以取消，回傳 Cancelled=true（rules-v2.md BR-01）
23	        // 已付款、尚未出貨的訂單取消時要提出退款要求（rules-v2.md BR-03，改）
24	        var cancelledOrder = order with { Cancelled = true };
25	        return new CancellationResult(cancelledOrder, RefundRequested: order.Paid);
26	    }
27	
28	    /// 這次呼叫有沒有真的把狀態從未取消改成已取消（通知的分母；非業務規則）。
29	    public static bool Transitioned(Order before, CancellationResult after) => !before.Cancelled && after.Order.Cancelled;
30	}
